function onlineToken(){try{return localStorage.getItem("zyrexOnlineToken")||""}catch{return ""}}
function onlineUser(){try{return localStorage.getItem("zyrexOnlineUser")||""}catch{return ""}}
async function onlineRequest(url,options={}){const token=onlineToken();const headers={"Content-Type":"application/json",...(options.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(url,{...options,headers});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw Error(d?.error||`HTTP ${r.status}`);return d}
function onlineToast(text){phase60Toast?.(text);const el=document.getElementById('onlineToast');if(el){el.textContent=text;el.classList.add('show');clearTimeout(onlineToast.t);onlineToast.t=setTimeout(()=>el.classList.remove('show'),2200)}}
async function onlineRegister(){const u=document.getElementById('onlineUsername')?.value.trim(),pw=document.getElementById('onlinePassword')?.value||'';try{const d=await onlineRequest('/api/auth/register',{method:'POST',body:JSON.stringify({username:u,password:pw})});localStorage.setItem('zyrexOnlineToken',d.token);localStorage.setItem('zyrexOnlineUser',d.username);onlineToast('ACCOUNT CREATED · '+d.username);refreshOnlineUI();await onlineLoadProfile()}catch(e){onlineToast(e.message)}}
async function onlineLogin(){const u=document.getElementById('onlineUsername')?.value.trim(),pw=document.getElementById('onlinePassword')?.value||'';try{const d=await onlineRequest('/api/auth/login',{method:'POST',body:JSON.stringify({username:u,password:pw})});localStorage.setItem('zyrexOnlineToken',d.token);localStorage.setItem('zyrexOnlineUser',d.username);onlineToast('LOGGED IN · '+d.username);refreshOnlineUI();await onlineLoadProfile()}catch(e){onlineToast(e.message)}}
function onlineLogout(){localStorage.removeItem('zyrexOnlineToken');localStorage.removeItem('zyrexOnlineUser');refreshOnlineUI();onlineToast('LOGGED OUT')}
function refreshOnlineUI(){const u=onlineUser(),label=document.getElementById('onlineStatus');if(label)label.textContent=u?`ONLINE · ${u}`:'LOCAL SAVE';const logout=document.getElementById('onlineLogout');if(logout)logout.style.display=u?'block':'none';const sync=document.getElementById('onlineSync');if(sync)sync.disabled=!u}
async function onlineSyncProfile(){if(!onlineToken())return;try{await onlineRequest('/api/profile',{method:'PUT',body:JSON.stringify({profile:collectProfile()})});onlineToast('CLOUD SAVE · SYNCED')}catch(e){onlineToast('CLOUD SAVE FAILED · '+e.message)}}
async function onlineLoadProfile(){if(!onlineToken())return;try{const d=await onlineRequest('/api/profile');if(d.profile){const p=d.profile;if(p.mods)Object.entries(p.mods).forEach(([id,v])=>localStorage.setItem('zyrexMod_'+id,JSON.stringify(v)));if(p.progression)Object.assign(progression,p.progression);if(p.economy)Object.assign(economy,p.economy);if(p.character)Object.assign(state.character,p.character);if(p.world)Object.assign(state,p.world);if(p.activeVehicle&&catalog.some(v=>v.id===p.activeVehicle))vehicleSelect.value=p.activeVehicle;saveEconomy();updateEconomyUI();updateMenuProfile();applyCharacterVisuals();onlineToast('CLOUD PROFILE · LOADED')}}catch(e){onlineToast('CLOUD LOAD FAILED · '+e.message)}}
async function submitLeaderboard(mode,score){if(!onlineToken())return;try{await onlineRequest('/api/leaderboard',{method:'POST',body:JSON.stringify({mode,score})});onlineToast('LEADERBOARD · SUBMITTED')}catch(e){onlineToast('LEADERBOARD · '+e.message)}}
async function loadLeaderboard(){const el=document.getElementById('leaderboardList');if(!el)return;try{const rows=await onlineRequest('/api/leaderboard?mode=race',{headers:{}});el.innerHTML=rows.length?rows.map((r,i)=>`<div class="lb-row"><b>#${i+1}</b><span>${r.username}</span><strong>${formatRaceTime(r.score)}</strong></div>`).join(''):'<div class="lb-empty">Belum ada score online.</div>'}catch(e){el.innerHTML=`<div class="lb-empty">${e.message}</div>`}}
function formatRaceTime(ms){const m=Math.floor(ms/60000),s=Math.floor(ms/1000)%60,cs=Math.floor(ms%1000/10);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(cs).padStart(2,'0')}`}
function setupPhase61to70UI(){if(document.getElementById('phase70Panel'))return;const v=document.querySelector('.viewport');if(!v)return;const panel=document.createElement('aside');panel.id='phase70Panel';panel.innerHTML='<div class="p70-head"><div><span class="eyebrow">PHASE 61–70</span><h2>ONLINE HUB</h2></div><button id="p70Close">×</button></div><div class="p70-status" id="onlineStatus">LOCAL SAVE</div><div class="p70-auth"><input id="onlineUsername" maxlength="20" placeholder="Username" autocomplete="username"><input id="onlinePassword" type="password" maxlength="128" placeholder="Password (8+ chars)" autocomplete="current-password"><div><button id="onlineLogin">LOGIN</button><button id="onlineRegister">REGISTER</button></div><button id="onlineLogout">LOGOUT</button></div><div class="p70-card"><b>Cloud Save</b><p>Save profile ke server ZYREX. Password tidak disimpan di browser.</p><button id="onlineSync">SYNC PROFILE</button><button id="onlineLoad">LOAD CLOUD SAVE</button></div><div class="p70-card"><b>Race Leaderboard</b><button id="onlineRefreshLb">REFRESH</button><div id="leaderboardList" class="lb-list">Loading…</div></div><p class="p70-note">Account API memakai token 7 hari dan password hashing server-side. Mode LOCAL tetap tersedia tanpa login.</p></aside>';v.appendChild(panel);const toast=document.createElement('div');toast.id='onlineToast';v.appendChild(toast);const menu=document.querySelector('.menu-actions');if(menu&&!document.getElementById('menuOnlineBtn')){const b=document.createElement('button');b.id='menuOnlineBtn';b.type='button';b.textContent='ONLINE';b.onclick=()=>{panel.classList.add('open');refreshOnlineUI();loadLeaderboard()};menu.appendChild(b)}document.getElementById('p70Close').onclick=()=>panel.classList.remove('open');document.getElementById('onlineLogin').onclick=onlineLogin;document.getElementById('onlineRegister').onclick=onlineRegister;document.getElementById('onlineLogout').onclick=onlineLogout;document.getElementById('onlineSync').onclick=onlineSyncProfile;document.getElementById('onlineLoad').onclick=onlineLoadProfile;document.getElementById('onlineRefreshLb').onclick=loadLeaderboard;refreshOnlineUI()}

const ECONOMY_KEY="zyrexDriveEconomy_v1";
const economy={cash:25000,owned:{e30_stance:true},totalEarned:0,totalSpent:0};
const progression={level:1,xp:0,totalXp:0};
const missionState={active:null,completed:0};
const MISSION_XP={delivery:120,checkpoint:90,speed:140};
const MISSION_REWARDS={delivery:2500,checkpoint:1800,speed:3000};
const MISSIONS=[
{id:'delivery-pasar',type:'delivery',name:'Antar Paket · Pasar',from:70,to:20,duration:90},
{id:'checkpoint-kampung',type:'checkpoint',name:'Checkpoint · Kampung',points:[40,-20,-100],duration:110},
{id:'speed-simpang',type:'speed',name:'Speed Challenge · Simpang',zone:[-55,-15],target:100,duration:55}
];
const vehiclePrices={fortuner_legender:65000,e30_stance:0,e92_stance:85000,e30_racing:110000,s1000rr:95000,diesel_family:40000,mustang_gt3:175000,aerox:30000,work_head:55000,yabaking:45000};
const modPrices={paint:750,ride:1200,camber:900,tune:3500,wheel:2500,lights:500,exhaust:3000,brake:1800};
function loadEconomy(){try{const p=JSON.parse(localStorage.getItem(ECONOMY_KEY)||"null");if(p){economy.cash=Number.isFinite(p.cash)?p.cash:25000;economy.owned={e30_stance:true,...(p.owned||{})};economy.totalEarned=+p.totalEarned||0;economy.totalSpent=+p.totalSpent||0}}catch{}}
function saveEconomy(){try{localStorage.setItem(ECONOMY_KEY,JSON.stringify(economy))}catch{}}
function formatMoney(n){return "Rp "+Math.max(0,Math.round(n)).toLocaleString("id-ID")}
function xpForLevel(l){return 300+(l-1)*125}
function addXP(amount,reason){progression.xp+=amount;progression.totalXp+=amount;while(progression.xp>=xpForLevel(progression.level)){progression.xp-=xpForLevel(progression.level);progression.level++;statusEl.textContent=`LEVEL UP · Lv ${progression.level}`;AudioEngine.raceBeep(980)}saveProfile(true);updateMissionUI()}
function missionById(id){return MISSIONS.find(m=>m.id===id)}
function finishMission(success,reason=''){const m=missionState.active;if(!m)return;missionState.active=null;if(success){const reward=MISSION_REWARDS[m.type]||1500;const xp=MISSION_XP[m.type]||100;earn(reward,`Mission reward · ${m.name}`);addXP(xp,`Mission XP · ${m.name}`);missionState.completed++;statusEl.textContent=`MISSION COMPLETE · +${formatMoney(reward)} · +${xp} XP`}else statusEl.textContent=`Mission failed${reason?` · ${reason}`:''}`;saveProfile(true);updateMissionUI()}
function startMission(id){if(!current||!isOwned(current.id)){statusEl.textContent='Buy vehicle first';return}if(missionState.active){statusEl.textContent='Finish current mission first';return}const base=missionById(id);if(!base)return;missionState.active={...base,startedAt:performance.now(),index:0,qualified:false};state.z=base.from??state.z;vehicleRoot.position.z=state.z;state.speed=0;statusEl.textContent=`MISSION START · ${base.name}`;updateMissionUI()}
function updateMission(dt){const m=missionState.active;if(!m||!vehicleRoot||!isOwned(current?.id))return;const elapsed=(performance.now()-m.startedAt)/1000;if(elapsed>m.duration){finishMission(false,'time up');return}if(m.type==='delivery'){if(routeDistance(state.z,m.to)<7)finishMission(true)}else if(m.type==='checkpoint'){const target=m.points[m.index];if(target!==undefined&&routeDistance(state.z,target)<7){m.index++;AudioEngine.raceBeep(860);if(m.index>=m.points.length)finishMission(true)}}else if(m.type==='speed'){const inZone=state.z>=Math.min(m.zone[0],m.zone[1])&&state.z<=Math.max(m.zone[0],m.zone[1]);if(inZone&&Math.abs(state.speed)*3.6>=m.target){m.qualified=true;finishMission(true)}}updateMissionUI()}
function ensureMissionUI(){if(document.getElementById('missionHud'))return;const box=document.createElement('div');box.id='missionHud';box.innerHTML='<div class="mission-head"><b>MISSIONS</b><span id="missionLevel">LV 1</span></div><div class="mission-xp"><i id="missionXpBar"></i></div><div class="mission-xptext" id="missionXpText">0 / 300 XP</div><div id="missionList"></div><div class="mission-active" id="missionActive">No active mission</div>';document.querySelector('.viewport')?.appendChild(box);const st=document.createElement('style');st.textContent='#missionHud{position:absolute;right:16px;top:16px;z-index:18;width:285px;padding:11px;background:rgba(5,7,10,.74);backdrop-filter:blur(9px);border:1px solid rgba(255,255,255,.12);border-radius:14px;color:#e9edf4;font:600 11px/1.35 system-ui;box-shadow:0 12px 40px rgba(0,0,0,.22)}#missionHud .mission-head{display:flex;justify-content:space-between;letter-spacing:.08em;margin-bottom:8px}#missionHud .mission-head span{opacity:.65}#missionHud .mission-xp{height:5px;background:#272b33;border-radius:99px;overflow:hidden}.mission-xp i{display:block;height:100%;width:0;background:#8b5cf6}.mission-xptext{font-size:9px;opacity:.55;margin:5px 0 9px}.mission-card{border-top:1px solid rgba(255,255,255,.08);padding:8px 0}.mission-card strong{display:block;font-size:11px}.mission-card small{display:block;opacity:.52;margin:2px 0 6px}.mission-card button{width:100%;padding:7px;border:1px solid rgba(255,255,255,.13);border-radius:8px;background:#171a20;color:#fff;font-weight:800;cursor:pointer}.mission-active{border-top:1px solid rgba(255,255,255,.1);padding-top:8px;margin-top:4px;font-weight:800}.mission-active small{display:block;opacity:.55;font-weight:600}.mission-active button{margin-top:5px;width:100%;padding:6px;border:1px solid rgba(255,255,255,.12);border-radius:8px;background:#171a20;color:#fff}@media(max-width:700px){#missionHud{width:235px;top:205px}}';document.head.appendChild(st);updateMissionUI()}
function updateMissionUI(){ensureMissionUI();const lvl=document.getElementById('missionLevel'),bar=document.getElementById('missionXpBar'),txt=document.getElementById('missionXpText'),list=document.getElementById('missionList'),active=document.getElementById('missionActive');if(!lvl)return;const need=xpForLevel(progression.level);lvl.textContent=`LV ${progression.level}`;bar.style.width=`${Math.round(progression.xp/need*100)}%`;txt.textContent=`${Math.round(progression.xp)} / ${need} XP · ${missionState.completed} completed`;if(list&&!missionState.active){list.innerHTML=MISSIONS.map(m=>`<div class="mission-card"><strong>${m.name}</strong><small>${m.type.toUpperCase()} · +${formatMoney(MISSION_REWARDS[m.type])} · +${MISSION_XP[m.type]} XP · ${m.duration}s</small><button type="button" data-mission="${m.id}">START</button></div>`).join('');list.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>startMission(b.dataset.mission))}else if(list&&missionState.active)list.innerHTML='';if(missionState.active){const m=missionState.active;const left=Math.max(0,m.duration-(performance.now()-m.startedAt)/1000);let detail='';if(m.type==='delivery')detail=`NEXT: PASAR · ${Math.round(routeDistance(state.z,m.to))} m`;if(m.type==='checkpoint')detail=`CHECKPOINT ${m.index}/${m.points.length} · ${m.points[m.index]===undefined?'DONE':Math.round(routeDistance(state.z,m.points[m.index]))+' m'}`;if(m.type==='speed')detail=`TARGET: ${m.target} km/h · ${m.qualified?'QUALIFIED':'find the zone'}`;active.innerHTML=`${m.name}<small>${detail} · ${Math.ceil(left)}s</small><button type="button" id="cancelMission">CANCEL</button>`;document.getElementById('cancelMission').onclick=()=>finishMission(false,'cancelled')}else active.textContent='No active mission'}
function vehiclePrice(v){return vehiclePrices[v?.id]??50000}
function isOwned(id){return economy.owned[id]===true}
function updateEconomyUI(){const cash=document.getElementById("cashValue");if(cash)cash.textContent=formatMoney(economy.cash);const own=document.getElementById("ownershipValue");if(own&&current)own.textContent=isOwned(current.id)?"OWNED":"LOCKED";const buy=document.getElementById("buyVehicle");if(buy&&current){const price=vehiclePrice(current);buy.disabled=isOwned(current.id)||economy.cash<price;buy.textContent=isOwned(current.id)?"OWNED · DRIVE":`BUY · ${formatMoney(price)}`}}
function spend(amount,reason){if(economy.cash<amount){statusEl.textContent=`Uang kurang · perlu ${formatMoney(amount-economy.cash)}`;return false}economy.cash-=amount;economy.totalSpent+=amount;saveEconomy();updateEconomyUI();statusEl.textContent=`-${formatMoney(amount)} · ${reason}`;return true}
function earn(amount,reason){economy.cash+=amount;economy.totalEarned+=amount;saveEconomy();updateEconomyUI();statusEl.textContent=`+${formatMoney(amount)} · ${reason}`}
function buyCurrentVehicle(){if(!current||isOwned(current.id))return;const price=vehiclePrice(current);if(!spend(price,`Bought ${current.name}`))return;economy.owned[current.id]=true;saveEconomy();updateEconomyUI();vehicleSelect.options[vehicleSelect.selectedIndex].textContent=current.name+" · OWNED";statusEl.textContent=`Purchased ${current.name} · ${formatMoney(economy.cash)} left`;refreshDealerOptions();refreshDealership();saveProfile(true)}
function economyVehicleChange(id){const v=catalog.find(x=>x.id===id);if(!v)return false;if(!isOwned(id))statusEl.textContent=`Preview · ${v.name} locked · buy to drive`;return true}
