function repairVehicle(){const repairCost=Math.ceil(state.damage*20);if(repairCost&&!spend(repairCost,"Vehicle repair"))return;state.damage=0;if(vehicleRoot?.userData?.materials)vehicleRoot.userData.materials.forEach(m=>{if(m.color)m.color.copy(new THREE.Color(paint.value))});applyVisuals();updateDamageVisual();statusEl.textContent="Vehicle repaired · 0% damage"}
