function buildNavigationSigns(){[-120,-60,60,120].forEach(z=>makeSpeedSign(z,60,z%120===0?1:-1));}

function buildIntersection(z){
  const cross=new THREE.Mesh(new THREE.BoxGeometry(52,.035,10),mat(0x202126,.97));cross.position.set(0,.075,z);world.add(cross);
  for(const x of [-9,-6,6,9]){const stripe=new THREE.Mesh(new THREE.BoxGeometry(1.25,.025,10),new THREE.MeshBasicMaterial({color:0xe8e4d7}));stripe.position.set(x,.105,z);world.add(stripe)}
  const poleX=12.2, poleZ=z-5.8;
  const pole=new THREE.Mesh(new THREE.CylinderGeometry(.11,.13,5.8,8),mat(0x25272b,.72,.6));pole.position.set(poleX,2.9,poleZ);world.add(pole);
  const head=new THREE.Mesh(new THREE.BoxGeometry(.5,1.35,.42),mat(0x16181c,.55,.3));head.position.set(poleX,5.0,poleZ);world.add(head);
  const bulbs=[];for(let i=0;i<3;i++){const m=new THREE.MeshStandardMaterial({color:0x111111,emissive:0x111111,emissiveIntensity:.1});const b=new THREE.Mesh(new THREE.SphereGeometry(.11,12,8),m);b.position.set(poleX,5.4-i*.42,poleZ-.22);world.add(b);bulbs.push(b)}
  worldFx.signals.push({bulbs,phaseOffset:0});
}
function updateSignals(dt){
  worldFx.signalPhase=(worldFx.signalPhase+dt)%18;
  const t=worldFx.signalPhase;
  worldFx.signalState=t<10?"green":t<13?"yellow":"red";
  for(const sig of worldFx.signals){const colors={green:0x31d66b,yellow:0xffc247,red:0xff4d5a};sig.bulbs.forEach((b,i)=>{const active=(worldFx.signalState==="green"&&i===2)||(worldFx.signalState==="yellow"&&i===1)||(worldFx.signalState==="red"&&i===0);b.material.emissive.setHex(active?colors[worldFx.signalState]:0x050505);b.material.emissiveIntensity=active?3:.05;b.material.color.setHex(active?colors[worldFx.signalState]:0x111111)})}
}


function makeLabel(text){
  const c=document.createElement('canvas');c.width=512;c.height=128;const x=c.getContext('2d');
  x.clearRect(0,0,512,128);x.fillStyle='rgba(5,7,10,.88)';x.roundRect(8,18,496,92,18);x.fill();
  x.fillStyle='#ffffff';x.font='800 38px Arial';x.textAlign='center';x.textBaseline='middle';x.fillText(text,256,64);
  const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;
  const m=new THREE.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false});const q=new THREE.Mesh(new THREE.PlaneGeometry(4.8,1.2),m);q.position.y=4.4;return q;
}
function makePoi(name,x,z,type){
  const g=new THREE.Group();
  const colors={gas:0xd63b32,workshop:0x8b5cf6,minimarket:0x2c9b68,parking:0x3f7bd9,landmark:0xe1a83a};
  const c=colors[type]||0x777777;
  const base=type==='landmark'?new THREE.CylinderGeometry(2.6,3.2,5.5,16):new THREE.BoxGeometry(7,3.2,8);
  const b=new THREE.Mesh(base,mat(c,.8,.18));b.position.y=type==='landmark'?2.75:1.6;b.castShadow=true;b.receiveShadow=true;g.add(b);
  if(type!=='landmark'){
    const roof=new THREE.Mesh(new THREE.BoxGeometry(7.4,.28,8.4),mat(0x22242a,.72,.4));roof.position.y=3.28;g.add(roof);
    for(const sx of [-2.2,0,2.2]){const win=new THREE.Mesh(new THREE.PlaneGeometry(1.45,1),new THREE.MeshStandardMaterial({color:0x9dc8d7,emissive:0x17252c,roughness:.28,metalness:.15}));win.position.set(sx,1.8,-4.03);g.add(win)}
  } else {
    const ring=new THREE.Mesh(new THREE.TorusGeometry(1.55,.22,10,28),mat(0xf4d35e,.45,.6));ring.position.y=5.3;g.add(ring);
    const spire=new THREE.Mesh(new THREE.ConeGeometry(.8,3.2,12),mat(0xeee6d2,.65,.25));spire.position.y=7.6;g.add(spire);
  }
  const label=makeLabel(name);g.add(label);g.position.set(x,0,z);world.add(g);worldFx.pois.push({name,type,group:g,position:g.position});
  if(type==='gas'){
    for(const px of [-2,0,2]){const pump=new THREE.Mesh(new THREE.BoxGeometry(.5,1.5,.7),mat(0xe9e6dd,.55,.15));pump.position.set(x+px,.75,z+5.2);world.add(pump)}
    const canopy=new THREE.Mesh(new THREE.BoxGeometry(8,.22,4),mat(0xf2f2ee,.5,.25));canopy.position.set(x,3.9,z+4);world.add(canopy);
  }
  if(type==='parking'){
    for(let i=-2;i<=2;i++){const mark=new THREE.Mesh(new THREE.BoxGeometry(.08,.02,3.6),new THREE.MeshBasicMaterial({color:0xe9e6d2}));mark.position.set(x+i*1.25,.08,z);world.add(mark)}
  }
}
