function makePedestrian(i){
  const g=new THREE.Group();const side=i%2?1:-1;const x=side*(15.2+Math.random()*1.5);const bodyColors=[0x3b4a6b,0x7c3f3f,0x4d654b,0x7a5a3a];
  const body=new THREE.Mesh(new THREE.CylinderGeometry(.18,.22,.72,8),mat(bodyColors[i%bodyColors.length],.9,.05));body.position.y=.72;g.add(body);
  const head=new THREE.Mesh(new THREE.SphereGeometry(.2,10,8),mat(0xc58b68,.85,0));head.position.y=1.28;g.add(head);
  const legMat=mat(0x23252a,.9,.05);for(const lx of [-.1,.1]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.12,.55,.12),legMat);leg.position.set(lx,.28,0);g.add(leg)}
  g.userData={side,baseX:x,speed:.45+Math.random()*.35,phase:Math.random()*Math.PI*2,direction:Math.random()<.5?1:-1};g.position.set(x,.02,-135+Math.random()*270);world.add(g);worldFx.pedestrians.push(g);
}
function initPedestrians(){worldFx.pedestrians.forEach(p=>world.remove(p));worldFx.pedestrians=[];for(let i=0;i<18;i++)makePedestrian(i)}
function updatePedestrians(dt){for(const p of worldFx.pedestrians){p.position.z+=p.userData.speed*p.userData.direction*dt;if(p.position.z>145)p.position.z=-145;if(p.position.z<-145)p.position.z=145;p.position.x=p.userData.baseX+Math.sin(performance.now()*.0015+p.userData.phase)*.35;p.rotation.y=p.userData.direction>0?0:Math.PI;p.children.forEach((c,j)=>{if(j>=2)c.rotation.x=Math.sin(performance.now()*.008+p.userData.phase+j)*.15})}}
function ensurePoiHUD(){if(document.getElementById('poiHud'))return;const box=document.createElement('div');box.id='poiHud';box.innerHTML='<div><small>NEARBY</small><strong id="poiName">—</strong></div><div><small>TYPE</small><strong id="poiType">—</strong></div><div><small>DISTANCE</small><strong id="poiDist">—</strong></div>';document.querySelector('.viewport')?.appendChild(box);const st=document.createElement('style');st.textContent='#poiHud{position:absolute;right:16px;top:16px;z-index:18;min-width:150px;padding:10px 12px;background:rgba(5,7,10,.72);backdrop-filter:blur(9px);border:1px solid rgba(255,255,255,.12);border-radius:12px;color:#e9edf4;font:600 10px/1.3 system-ui}.poiHud{}#poiHud small{display:block;opacity:.48;font-size:8px;letter-spacing:.1em}#poiHud strong{display:block;font-size:12px;margin-bottom:5px}@media(max-width:700px){#poiHud{top:150px;right:10px;min-width:125px}}';document.head.appendChild(st)}
function updatePoiHUD(){if(!worldFx.pois.length||!vehicleRoot)return;let best=null,bd=Infinity;for(const p of worldFx.pois){const dx=p.position.x-vehicleRoot.position.x,dz=p.position.z-vehicleRoot.position.z;const d=Math.hypot(dx,dz);if(d<bd){bd=d;best=p}}const n=document.getElementById('poiName'),t=document.getElementById('poiType'),d=document.getElementById('poiDist');if(n)n.textContent=best?.name||'—';if(t)t.textContent=best?.type?.toUpperCase()||'—';if(d)d.textContent=bd<1000?`${Math.round(bd)} m`:'—'}

async function loadEnvironment(){
  try{const gltf=await new Promise((resolve,reject)=>loader.load('/assets/environment/warung_nasi_padang.glb',resolve,undefined,reject));const env=gltf.scene;const box=new THREE.Box3().setFromObject(env),size=box.getSize(new THREE.Vector3()),scale=10/Math.max(size.x,size.z,1);env.scale.setScalar(scale);env.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(env);env.position.set(-10,-b.min.y, -55);env.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});world.add(env);worldFx.environment=env}catch(e){console.warn('Environment asset skipped',e)}
}
function makeTrafficVehicle(i){
  const g=new THREE.Group();
  const body=mat([0x22252b,0x7d2730,0xb7a84f,0x2e596d,0xd7d7d7][i%5],.65,.35);
  const shell=new THREE.Mesh(new THREE.BoxGeometry(1.7,.65,3.6),body);shell.position.y=.58;g.add(shell);
  const roof=new THREE.Mesh(new THREE.BoxGeometry(1.35,.42,1.8),body);roof.position.y=1.05;roof.position.z=.15;g.add(roof);
  for(const x of [-.76,.76])for(const z of [-1.2,1.2]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.27,.27,.16,12),mat(0x141519,.7,.8));w.rotation.z=Math.PI/2;w.position.set(x,.34,z);g.add(w)}
  const frontMat=new THREE.MeshStandardMaterial({color:0xf4f0d0,emissive:0xf4d58b,emissiveIntensity:.7});
  const rearMat=new THREE.MeshStandardMaterial({color:0x5d1118,emissive:0x180306,emissiveIntensity:.25});
  for(const x of [-.55,.55]){const f=new THREE.Mesh(new THREE.SphereGeometry(.08,8,6),frontMat);f.position.set(x,.67,-1.83);g.add(f);const r=new THREE.Mesh(new THREE.SphereGeometry(.08,8,6),rearMat);r.position.set(x,.67,1.83);g.add(r);}
  g.userData={speed:6+Math.random()*5,lane:i%2?5.5:-5.5,baseSpeed:6+Math.random()*5,brakeLights:g.children.filter(o=>o.material===rearMat),stopped:false};
  g.position.set(g.userData.lane,0,-120-i*28);g.rotation.y=g.userData.lane>0?Math.PI:0;world.add(g);worldFx.traffic.push(g)
}
function initTraffic(){if(!state.traffic)return;worldFx.traffic.forEach(v=>world.remove(v));worldFx.traffic=[];for(let i=0;i<10;i++)makeTrafficVehicle(i)}
function updateTraffic(dt){
  if(!state.traffic)return;
  for(let i=0;i<worldFx.traffic.length;i++){
    const v=worldFx.traffic[i], dir=v.userData.lane>0?1:-1;
    const atSignal=Math.abs(v.position.z)<9;
    let target=v.userData.baseSpeed;
    if(atSignal && worldFx.signalState!=="green") target=worldFx.signalState==="yellow"?v.userData.baseSpeed*.35:0;
    for(let j=0;j<worldFx.traffic.length;j++){if(i===j)continue;const o=worldFx.traffic[j];if(o.userData.lane!==v.userData.lane)continue;const gap=(o.position.z-v.position.z)*dir;if(gap>0&&gap<9)target=Math.min(target,Math.max(0,o.userData.speed-2));}
    v.userData.speed=THREE.MathUtils.lerp(v.userData.speed,target,Math.min(1,dt*4));
    v.userData.stopped=v.userData.speed<.35;
    v.position.z+=v.userData.speed*dt*dir;
    v.userData.brakeLights.forEach(l=>{l.material.emissiveIntensity=v.userData.stopped||target<v.userData.baseSpeed*.75?2.5:.25});
    if(dir>0&&v.position.z>155)v.position.z=-165-Math.random()*25;
    if(dir<0&&v.position.z<-155)v.position.z=165+Math.random()*25;
  }
}

function createRaceGate(z,final=false){const g=new THREE.Group();const poleMat=mat(0x25262c,.7,.5);for(const x of [-11,11]){const p=new THREE.Mesh(new THREE.CylinderGeometry(.12,.16,4.8,10),poleMat);p.position.set(x,2.4,z);g.add(p)}const bar=new THREE.Mesh(new THREE.BoxGeometry(22,.3,.35),mat(final?0x8b5cf6:0x30323a,.45,.65));bar.position.set(0,4.6,z);g.add(bar);world.add(g);worldFx.raceGates.push(g)}
function clearRaceVisuals(){worldFx.racers.forEach(r=>world.remove(r));worldFx.racers=[];worldFx.raceGates.forEach(g=>world.remove(g));worldFx.raceGates=[]}
function makeRaceOpponent(i){const g=new THREE.Group();const body=mat([0x2f3540,0xb12f3f,0xddd7c7,0x345f7a][i%4],.58,.42);const shell=new THREE.Mesh(new THREE.BoxGeometry(1.8,.62,3.7),body);shell.position.y=.58;g.add(shell);const roof=new THREE.Mesh(new THREE.BoxGeometry(1.35,.4,1.7),body);roof.position.y=1.02;g.add(roof);for(const x of [-.78,.78])for(const z of [-1.25,1.25]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.25,.25,.15,12),mat(0x121318,.72,.8));w.rotation.z=Math.PI/2;w.position.set(x,.34,z);g.add(w)}const lamp=new THREE.Mesh(new THREE.BoxGeometry(1.25,.08,.05),new THREE.MeshStandardMaterial({color:0xffdf9b,emissive:0xffbf66,emissiveIntensity:1.5}));lamp.position.set(0,.72,-1.88);g.add(lamp);g.userData={lane:(i-1.5)*3.5,speed:8+i*.5,skill:.9+i*.045,progress:0};g.position.set(g.userData.lane,0,-140-i*7);g.rotation.y=Math.PI;world.add(g);worldFx.racers.push(g)}
function racePosition(){const arr=[{name:"YOU",progress:worldFx.race.lap*300+THREE.MathUtils.clamp(state.z+140,0,300),player:true}];worldFx.racers.forEach(r=>arr.push({name:"AI",progress:r.userData.progress}));arr.sort((a,b)=>b.progress-a.progress);return arr.findIndex(x=>x.player)+1}
function updateRaceHUD(){const r=worldFx.race;if(!r.active&&!r.finished){$("#raceState").textContent="FREE DRIVE";$("#raceLap").textContent="0 / 3";$("#racePos").textContent="—";$("#raceTime").textContent="00:00.00";return}const mm=String(Math.floor(r.elapsed/60)).padStart(2,"0"),ss=(r.elapsed%60).toFixed(2).padStart(5,"0");$("#raceState").textContent=r.finished?"FINISH":r.countdown>0?String(Math.ceil(r.countdown)):"RACING";$("#raceLap").textContent=`${Math.min(r.lap+1,r.totalLaps)} / ${r.totalLaps}`;$("#racePos").textContent=`${racePosition()} / ${worldFx.racers.length+1}`;$("#raceTime").textContent=`${mm}:${ss}`;$("#nitroBar").style.width=`${state.nitro}%`}
function startRace(){if(!vehicleRoot||worldFx.race.active||!isOwned(current?.id)){statusEl.textContent="Buy this vehicle before racing";return;}clearRaceVisuals();const r=worldFx.race;r.active=true;r.finished=false;r.countdown=3;r.elapsed=0;r.lap=0;r.nextCheckpoint=0;r.startAt=performance.now()+3000;state.speed=0;state.z=-140;state.heading=Math.PI;state.nitro=100;state.nitroActive=false;vehicleRoot.position.set(0,originalY+state.ride,-140);vehicleRoot.rotation.set(0,Math.PI,0);for(let i=0;i<4;i++)makeRaceOpponent(i);[-80,-20,40,100].forEach(z=>createRaceGate(z,false));createRaceGate(140,true);garage.classList.remove("open");statusEl.textContent="Race starting…";updateRaceHUD()}
function finishRace(){const r=worldFx.race;const pos=racePosition();r.active=false;r.finished=true;state.nitroActive=false;keys.up=false;const prev=r.bestTimes?.[current.id];const rewards=[5000,3000,2000,1000,750];const reward=rewards[Math.min(pos-1,rewards.length-1)]||500;if(pos===1&&(!prev||r.elapsed<prev))r.bestTimes[current.id]=r.elapsed;if(pos===1)submitLeaderboard("race",r.elapsed);earn(reward,`Race reward · P${pos}`);saveProfile(true);statusEl.textContent=`${pos===1?"🏆 ":""}Race finished · P${pos} · +${formatMoney(reward)}`;updateRaceHUD()}
function updateRace(dt){const r=worldFx.race;if(!r.active)return;if(r.countdown>0){r.countdown=Math.max(0,(r.startAt-performance.now())/1000);if(r.countdown===0)statusEl.textContent="GO!";updateRaceHUD();return}r.elapsed+=dt;worldFx.racers.forEach((v,i)=>{const target=10.2+i*.35;v.userData.speed=THREE.MathUtils.lerp(v.userData.speed,target,Math.min(1,dt*2));v.position.z+=v.userData.speed*dt;if(v.position.z>=140){v.position.z=-140;r.lap=Math.max(r.lap,0);v.userData.progress+=300}else v.userData.progress=(v.userData.progress||0)+v.userData.speed*dt});if(state.z>=140){state.z=-140;vehicleRoot.position.z=-140;r.lap++;r.nextCheckpoint=0;if(r.lap>=r.totalLaps){finishRace();return}}const cps=[-80,-20,40,100];if(r.nextCheckpoint<cps.length&&state.z>=cps[r.nextCheckpoint])r.nextCheckpoint++;updateRaceHUD()}

function ensureNavigationUI(){
  if(document.getElementById("navHud"))return;
  const box=document.createElement("div");box.id="navHud";box.innerHTML='<div class="nav-title"><b>GPS</b><span id="navRouteName">CITY LOOP</span></div><div class="nav-main"><canvas id="miniMap" width="180" height="180"></canvas><div class="nav-data"><div><small>NEXT</small><strong id="navNext">—</strong></div><div><small>DISTANCE</small><strong id="navDistance">—</strong></div><div><small>LIMIT</small><strong id="navLimit">60 km/h</strong></div><div><small>ETA</small><strong id="navEta">—</strong></div></div></div>';document.querySelector('.viewport')?.appendChild(box);
  const st=document.createElement('style');st.textContent='#navHud{position:absolute;left:16px;top:16px;z-index:18;width:310px;padding:10px;background:rgba(5,7,10,.72);backdrop-filter:blur(9px);border:1px solid rgba(255,255,255,.12);border-radius:14px;color:#e9edf4;font:600 11px/1.35 system-ui;box-shadow:0 12px 40px rgba(0,0,0,.22)}#navHud .nav-title{display:flex;justify-content:space-between;letter-spacing:.08em;margin-bottom:8px}#navHud .nav-title b{color:#fff}#navHud .nav-title span{opacity:.55}#navHud .nav-main{display:flex;gap:10px;align-items:center}#miniMap{width:180px;height:180px;border-radius:10px;background:#101319;border:1px solid rgba(255,255,255,.08)}#navHud .nav-data{display:grid;gap:8px;flex:1}#navHud small{display:block;opacity:.48;font-size:9px}#navHud strong{font-size:13px}#navHud.hidden{display:none}@media(max-width:700px){#navHud{width:235px}#miniMap{width:125px;height:125px}#navHud .nav-data{gap:5px}}';document.head.appendChild(st);
  state.navVisible=state.navVisible!==false;
}
function initNavigation(){
  worldFx.navRoute=[{z:70,name:'START'},{z:20,name:'PASAR'},{z:-40,name:'SIMPANG'},{z:-100,name:'KAMPUNG'},{z:-145,name:'U-TURN'}];worldFx.navIndex=1;ensureNavigationUI();
}
function routeDistance(a,b){let d=Math.abs(a-b);return Math.min(d,300-d)}
function updateNavigation(){
  if(!vehicleRoot)return;ensureNavigationUI();const hud=document.getElementById('navHud');if(hud)hud.classList.toggle('hidden',state.navVisible===false);if(state.navVisible===false)return;
  const route=worldFx.navRoute;if(!route.length)return;let target=route[worldFx.navIndex];let dz=target.z-state.z;if(Math.abs(dz)<8){worldFx.navIndex=(worldFx.navIndex+1)%route.length;target=route[worldFx.navIndex];dz=target.z-state.z;}const dist=routeDistance(state.z,target.z);worldFx.navDistance=dist;worldFx.navEta=Math.max(0,dist/Math.max(3,Math.abs(state.speed)));
  const next=document.getElementById('navNext'),distance=document.getElementById('navDistance'),eta=document.getElementById('navEta'),limit=document.getElementById('navLimit');if(next)next.textContent=target.name;if(distance)distance.textContent=`${Math.round(dist)} m`;if(eta)eta.textContent=state.speed>1?`${Math.ceil(worldFx.navEta)} s`:'—';const localLimit=Math.abs(state.z)<12?30:60;if(limit)limit.textContent=`${localLimit} km/h`;
  const c=document.getElementById('miniMap');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#101319';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#343941';ctx.lineWidth=20;ctx.beginPath();ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.stroke();ctx.strokeStyle='#d4d6da';ctx.lineWidth=1.5;ctx.setLineDash([7,7]);ctx.beginPath();ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.stroke();ctx.setLineDash([]);
  for(const z of [-120,-60,0,60,120]){const y=THREE.MathUtils.mapLinear(z,-160,160,h-12,12);ctx.strokeStyle='#3c414a';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(10,y);ctx.lineTo(w-10,y);ctx.stroke();}
  const py=THREE.MathUtils.mapLinear(THREE.MathUtils.clamp(state.z,-160,160),-160,160,h-18,18);const tx= w/2;const ty=THREE.MathUtils.mapLinear(target.z,-160,160,h-18,18);ctx.fillStyle='#8b5cf6';ctx.beginPath();ctx.arc(tx,ty,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff';ctx.beginPath();ctx.moveTo(tx,py-10);ctx.lineTo(tx-7,py+7);ctx.lineTo(tx+7,py+7);ctx.closePath();ctx.fill();ctx.fillStyle='#f1c75b';for(const v of worldFx.traffic){const vy=THREE.MathUtils.mapLinear(THREE.MathUtils.clamp(v.position.z,-160,160),-160,160,h-18,18);ctx.beginPath();ctx.arc(w/2+(v.position.x>0?22:-22),vy,2.5,0,Math.PI*2);ctx.fill();}
}
function toggleNavigation(){state.navVisible=state.navVisible===false;statusEl.textContent=`GPS ${state.navVisible?'ON':'OFF'}`;updateNavigation()}

function setWeather(mode){state.weather=mode;if(worldFx.rain){world.remove(worldFx.rain);worldFx.rain=null}if(mode==='rain'){const geo=new THREE.BufferGeometry(),n=1100,arr=new Float32Array(n*3);for(let i=0;i<n;i++){arr[i*3]=(Math.random()-.5)*80;arr[i*3+1]=Math.random()*35;arr[i*3+2]=(Math.random()-.5)*220}geo.setAttribute('position',new THREE.BufferAttribute(arr,3));const m=new THREE.PointsMaterial({color:0xa9c8e8,size:.07,transparent:true,opacity:.62});worldFx.rain=new THREE.Points(geo,m);world.add(worldFx.rain)}}
function updateWeather(dt){if(state.weather==='rain'&&worldFx.rain){const a=worldFx.rain.geometry.attributes.position.array;for(let i=1;i<a.length;i+=3){a[i]-=28*dt;if(a[i]<0)a[i]=35}worldFx.rain.geometry.attributes.position.needsUpdate=true}}
function applyTimeOfDay(){const t=state.timeOfDay,night=t>.68||t<.18;state.night=night;const daylight=Math.max(0,Math.sin((t-.18)*Math.PI/0.5));sun.intensity=night?.18:1.1+daylight*1.5;scene.background.set(night?0x030611:state.weather==='rain'?0x5b6670:0x87b0d6);scene.fog.color.copy(scene.background);scene.fog.near=night?55:90;scene.fog.far=night?220:300;scene.traverse(o=>{if(o.isHemisphereLight)o.intensity=night?.55:1.7});worldFx.streetLights.forEach(x=>{x.light.intensity=night?2.4:0;x.lamp.material.emissiveIntensity=night?3:.8});if(vehicleRoot)applyVisuals()}
function cycleTime(){state.timeOfDay=(state.timeOfDay+.12)%1;applyTimeOfDay();statusEl.textContent=`Time: ${state.night?'Night':'Day'} · ${state.weather}`}

async function loadCatalog(){const r=await fetch("/game-assets.json");if(!r.ok)throw Error("game-assets.json HTTP "+r.status);const d=await r.json();catalog=d.vehicles;catalog.forEach(v=>{const o=document.createElement("option");o.value=v.id;o.textContent=isOwned(v.id)?`${v.name} · OWNED`:`${v.name} · ${formatMoney(vehiclePrice(v))}`;o.disabled=false;vehicleSelect.appendChild(o)});return d}
function normalizeModel(root){const box=new THREE.Box3().setFromObject(root),size=box.getSize(new THREE.Vector3()),max=Math.max(size.x,size.y,size.z),scale=(current.type==="bike"?2.4:4.3)/max;root.scale.setScalar(scale);root.updateMatrixWorld(true);const b2=new THREE.Box3().setFromObject(root);root.position.y-=b2.min.y;const center=b2.getCenter(new THREE.Vector3());root.position.x-=center.x;root.position.z-=center.z;root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}})}
function identifyWheels(root){const wheels=[];root.traverse(o=>{const n=(o.name||"").toLowerCase();if(/wheel|tire|tyre|banblkng|roda|pneu/.test(n)){o.userData.baseRotation=o.rotation.clone();o.userData.baseScale=o.scale.clone();wheels.push(o)}});return wheels}
function vehicleSpec(v){return {bike:v.type==="bike",max:v.maxKmh/3.6,drive:v.drive||"RWD",grip:v.type==="bike"?1.12:1,mass:v.type==="bike"?1:1.45,steerRate:v.type==="bike"?1.25:.92};}
function collectMaterials(root){const out=[];root.traverse(o=>{if(o.isMesh&&o.material){(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>{if(m.color&&!out.includes(m))out.push(m)})}});return out}
function addVehicleLights(root){const g=new THREE.Group();g.name="ZYREX_LIGHTS";const specs=[[-.72,.72,-1.55],[.72,.72,-1.55]];specs.forEach(([x,y,z])=>{const lamp=new THREE.Mesh(new THREE.SphereGeometry(.11,12,8),new THREE.MeshStandardMaterial({color:0xeef7ff,emissive:0xdceeff,emissiveIntensity:2.5,roughness:.25,metalness:.1}));lamp.position.set(x,y,z);g.add(lamp);const p=new THREE.PointLight(0xdbeeff,2.2,18,2);p.position.set(x,y,z);p.userData.baseIntensity=2.2;g.add(p)});root.add(g);root.userData.lightsGroup=g}
function addExhaust(root){const g=new THREE.Group();g.name="ZYREX_EXHAUST";const z=1.65;for(const x of [-.42,.42]){const tip=new THREE.Mesh(new THREE.CylinderGeometry(.08,.11,.28,12),new THREE.MeshStandardMaterial({color:0x9b9b9b,metalness:.9,roughness:.22}));tip.rotation.x=Math.PI/2;tip.position.set(x,.5,z);g.add(tip);const glow=new THREE.Mesh(new THREE.SphereGeometry(.045,10,8),new THREE.MeshBasicMaterial({color:0xffa04a,transparent:true,opacity:0}));glow.position.set(x,.5,z+.15);g.add(glow)}root.add(g);root.userData.exhaustGroup=g}
function makeWheelCaps(root){const group=new THREE.Group();group.name="ZYREX_WHEEL_CAPS";const bike=current.type==="bike";const positions=bike?[[0,.48,-1.0],[0,.48,1.0]]:[[-.82,.48,-1.22],[.82,.48,-1.22],[-.82,.48,1.22],[.82,.48,1.22]];positions.forEach(([x,y,z])=>{const ring=new THREE.Mesh(new THREE.TorusGeometry(bike?.26:.34,.055,8,20),new THREE.MeshStandardMaterial({color:0x15161a,metalness:.85,roughness:.22}));ring.rotation.y=Math.PI/2;ring.position.set(x,y,z);group.add(ring)});root.add(group);root.userData.wheelCaps=group}
async function loadVehicle(id){const next=catalog.find(v=>v.id===id)||catalog[0];current=next;statusEl.textContent=`Loading ${next.name}…`;progress.style.width="15%";loading.classList.remove("hide");if(vehicleRoot)scene.remove(vehicleRoot);state.speed=0;state.z=70;state.heading=Math.PI;state.ride=0;state.camber=0;state.suspension=0;
const gltf=await new Promise((resolve,reject)=>loader.load(next.file,resolve,p=>{if(p.total)progress.style.width=`${15+Math.min(70,p.loaded/p.total*70)}%`},reject));vehicleRoot=gltf.scene;normalizeModel(vehicleRoot);vehicleRoot.position.set(0,0,70);vehicleRoot.rotation.y=Math.PI;scene.add(vehicleRoot);originalY=vehicleRoot.position.y;vehicleRoot.userData.wheels=identifyWheels(vehicleRoot);vehicleRoot.userData.materials=collectMaterials(vehicleRoot);addVehicleLights(vehicleRoot);addExhaust(vehicleRoot);makeWheelCaps(vehicleRoot);vehicleName.textContent=next.name;vehicleMeta.textContent=`${next.drive} · ${next.maxKmh} km/h · ${next.type.toUpperCase()}`;vehicleSelect.value=next.id;applySaved();refreshDealership();progress.style.width="100%";loadingText.textContent="Vehicle ready.";setTimeout(()=>loading.classList.add("hide"),180);statusEl.textContent="Garage ready · Phase 9"}
function applySaved(){let saved=null;try{saved=JSON.parse(localStorage.getItem("zyrexMod_"+current.id)||"null")}catch{}const s=saved||{paint:"#8b5cf6",ride:0,camber:0,tune:1,wheelStyle:"stock",lights:"auto",exhaust:"stock",brakeBias:1};paint.value=s.paint;ride.value=s.ride;camber.value=s.camber;tune.value=s.tune;wheelStyle.value=s.wheelStyle||"stock";lights.value=s.lights||"auto";exhaust.value=s.exhaust||"stock";brakeBias.value=s.brakeBias||1;state.tune=+s.tune;state.ride=+s.ride;state.camber=+s.camber;state.wheelStyle=wheelStyle.value;state.lightMode=lights.value;state.exhaustStyle=exhaust.value;state.brakeBias=+brakeBias.value;applyVisuals()}
function applyVisuals(){if(!vehicleRoot)return;const c=new THREE.Color(paint.value);vehicleRoot.userData.materials?.forEach(m=>{if(m.color)m.color.copy(c)});vehicleRoot.position.y=originalY+state.ride+state.suspension;vehicleRoot.userData.wheels?.forEach(w=>{w.rotation.z=w.userData.baseRotation.z+state.camber});
const style=state.wheelStyle;const wheels=vehicleRoot.userData.wheels||[];wheels.forEach(w=>{const s=w.userData.baseScale.clone();const f=style==="deep"?1.08:style==="sport"?1.035:style==="mesh"?.99:1;w.scale.copy(s).multiplyScalar(f);if(w.material){const ms=Array.isArray(w.material)?w.material:[w.material];ms.forEach(m=>{if(m.metalness!==undefined)m.metalness=style==="stock"?.65:.9;if(m.roughness!==undefined)m.roughness=style==="mesh"?.35:.2})}});
if(vehicleRoot.userData.wheelCaps)vehicleRoot.userData.wheelCaps.visible=style!=="stock";const ex=vehicleRoot.userData.exhaustGroup;if(ex){const map={stock:[.08,.11],performance:[.11,.15],titanium:[.13,.17]};const [a,b]=map[state.exhaustStyle]||map.stock;ex.children.filter(x=>x.isMesh).forEach(x=>{if(x.geometry?.type==="CylinderGeometry"){x.scale.set(a/.08,b/.11,1)}})}const lg=vehicleRoot.userData.lightsGroup;if(lg){const on=state.lightMode==="on"||(state.lightMode==="auto"&&state.night);lg.children.forEach(x=>{if(x.isLight)x.intensity=on?x.userData.baseIntensity:0;if(x.material?.emissiveIntensity!==undefined)x.material.emissiveIntensity=on?2.5:0.15})}}
function saveMod(){localStorage.setItem("zyrexMod_"+current.id,JSON.stringify({paint:paint.value,ride:+ride.value,camber:+camber.value,tune:+tune.value,wheelStyle:wheelStyle.value,lights:lights.value,exhaust:exhaust.value,brakeBias:+brakeBias.value}))}
const PROFILE_KEY="zyrexDriveProfile_v1";
function collectMods(){const out={};for(const v of catalog){try{const raw=localStorage.getItem("zyrexMod_"+v.id);if(raw)out[v.id]=JSON.parse(raw)}catch{}}return out}
function applyGraphics(){const q=quality?.value||"medium";const d=q==="low"?.75:q==="high"?1.5:1;renderer.setPixelRatio(Math.min(devicePixelRatio||1,d));renderer.shadowMap.enabled=(shadows?.value||"on")==="on";scene.fog.far=q==="low"?190:q==="high"?340:300;statusEl.textContent=`Graphics: ${q.toUpperCase()} · Shadows ${renderer.shadowMap.enabled?"ON":"OFF"}`;}
function collectProfile(){const best=worldFx.race.bestTimes||{};return {version:5,savedAt:new Date().toISOString(),activeVehicle:vehicleSelect.value,mods:collectMods(),economy:{cash:economy.cash,owned:economy.owned,totalEarned:economy.totalEarned,totalSpent:economy.totalSpent},progression:{level:progression.level,xp:progression.xp,totalXp:progression.totalXp,completed:missionState.completed},world:{timeOfDay:state.timeOfDay,weather:state.weather,traffic:state.traffic},graphics:{quality:quality?.value||"medium",shadows:shadows?.value||"on"},controls:state.controls,character:state.character,bestTimes:best,phase30:{onFoot:false,achievements:state.achievements,playSeconds:state.playSeconds,vehiclesDriven:state.vehiclesDriven,metersDriven:state.metersDriven,interactions:state.interactions}}}
function saveProfile(silent=false){try{localStorage.setItem(PROFILE_KEY,JSON.stringify(collectProfile()));if(onlineToken()) onlineSyncProfile();if(!silent)statusEl.textContent="Profile saved"}catch(e){statusEl.textContent="Profile save failed"}}
function loadProfile(silent=false){try{const p=JSON.parse(localStorage.getItem(PROFILE_KEY)||"null");if(!p)return false;if(p.mods)Object.entries(p.mods).forEach(([id,v])=>localStorage.setItem("zyrexMod_"+id,JSON.stringify(v)));if(p.progression){progression.level=Math.max(1,+p.progression.level||1);progression.xp=Math.max(0,+p.progression.xp||0);progression.totalXp=Math.max(0,+p.progression.totalXp||0);missionState.completed=Math.max(0,+p.progression.completed||0)}if(p.economy){economy.cash=Number.isFinite(p.economy.cash)?p.economy.cash:economy.cash;economy.owned={e30_stance:true,...(p.economy.owned||{})};economy.totalEarned=+p.economy.totalEarned||0;economy.totalSpent=+p.economy.totalSpent||0;saveEconomy();updateEconomyUI()}if(p.world){state.timeOfDay=Number.isFinite(p.world.timeOfDay)?p.world.timeOfDay:state.timeOfDay;state.weather=p.world.weather||state.weather;state.traffic=p.world.traffic!==false}if(p.audio){state.audio={...state.audio,...p.audio};if(masterVolume)masterVolume.value=state.audio.master;if(engineVolume)engineVolume.value=state.audio.engine;if(effectsVolume)effectsVolume.value=state.audio.effects;if(ambienceVolume)ambienceVolume.value=state.audio.ambience;AudioEngine.applyVolumes()}if(p.graphics){if(quality)quality.value=p.graphics.quality||"medium";if(shadows)shadows.value=p.graphics.shadows||"on";applyGraphics()}if(p.controls){state.controls={...state.controls,...p.controls,bindings:{...state.controls.bindings,...(p.controls.bindings||{})}};refreshControlUI()}if(p.character){state.character={...state.character,...p.character};applyCharacterVisuals()}if(p.bestTimes)worldFx.race.bestTimes=p.bestTimes;if(p.phase30){state.achievements={...(p.phase30.achievements||{})};state.playSeconds=Math.max(0,+p.phase30.playSeconds||0);state.vehiclesDriven=Math.max(0,+p.phase30.vehiclesDriven||0);state.metersDriven=Math.max(0,+p.phase30.metersDriven||0);state.interactions=Math.max(0,+p.phase30.interactions||0)}if(p.activeVehicle)vehicleSelect.value=p.activeVehicle;if(!silent)statusEl.textContent="Profile loaded";return !!p.activeVehicle}catch(e){statusEl.textContent="Profile load failed";return false}}
function savePreset(){if(!current)return;const key=`zyrexPreset_${presetSlot.value}_${current.id}`;localStorage.setItem(key,JSON.stringify({paint:paint.value,ride:+ride.value,camber:+camber.value,tune:+tune.value,wheelStyle:wheelStyle.value,lights:lights.value,exhaust:exhaust.value,brakeBias:+brakeBias.value}));statusEl.textContent=`Preset ${presetSlot.value} saved`}
function loadPreset(){if(!current)return;try{const s=JSON.parse(localStorage.getItem(`zyrexPreset_${presetSlot.value}_${current.id}`)||"null");if(!s){statusEl.textContent=`Preset ${presetSlot.value} empty`;return}paint.value=s.paint||"#8b5cf6";ride.value=s.ride??0;camber.value=s.camber??0;tune.value=s.tune??1;wheelStyle.value=s.wheelStyle||"stock";lights.value=s.lights||"auto";exhaust.value=s.exhaust||"stock";brakeBias.value=s.brakeBias??1;state.ride=+ride.value;state.camber=+camber.value;state.tune=+tune.value;state.wheelStyle=wheelStyle.value;state.lightMode=lights.value;state.exhaustStyle=exhaust.value;state.brakeBias=+brakeBias.value;applyVisuals();saveMod();statusEl.textContent=`Preset ${presetSlot.value} loaded`}catch{statusEl.textContent="Preset load failed"}}


function fmtKmh(v){return `${Math.round(v)} km/h`}
function dealershipScore(v){const speed=Number(v?.maxKmh||0);const drive=v?.drive||'';const bike=v?.type==='bike'?8:0;const driveBonus=/AWD/i.test(drive)?7:/RWD/i.test(drive)?5:3;return Math.round(Math.min(100,28+speed*.25+bike+driveBonus))}
