const AudioEngine={ctx:null,master:null,engineGain:null,engineOsc:null,engineOsc2:null,engineFilter:null,exhaustGain:null,exhaustNoise:null,exhaustFilter:null,turboOsc:null,fxGain:null,skidGain:null,skidNoise:null,ambGain:null,ambNoise:null,started:false,lastCollision:0,start(){if(this.started){this.resume();return}const C=window.AudioContext||window.webkitAudioContext;if(!C)return;this.ctx=new C();this.master=this.ctx.createGain();this.master.gain.value=state.audio.master;this.master.connect(this.ctx.destination);this.engineGain=this.ctx.createGain();this.engineOsc=this.ctx.createOscillator();this.engineOsc2=this.ctx.createOscillator();this.engineFilter=this.ctx.createBiquadFilter();this.engineFilter.type="lowpass";this.engineOsc.type="sawtooth";this.engineOsc2.type="square";this.engineOsc.connect(this.engineFilter);this.engineOsc2.connect(this.engineFilter);this.engineFilter.connect(this.engineGain).connect(this.master);this.engineOsc.start();this.engineOsc2.start();this.exhaustGain=this.ctx.createGain();this.exhaustNoise=this.ctx.createBufferSource();this.exhaustNoise.buffer=this.noiseBuffer(.45);this.exhaustNoise.loop=true;this.exhaustFilter=this.ctx.createBiquadFilter();this.exhaustFilter.type="lowpass";this.exhaustNoise.connect(this.exhaustFilter).connect(this.exhaustGain).connect(this.master);this.exhaustNoise.start();this.turboOsc=this.ctx.createOscillator();this.turboOsc.type="sine";const tg=this.ctx.createGain();this.turboOsc.connect(tg).connect(this.master);this.turboGain=tg;this.turboOsc.start();this.fxGain=this.ctx.createGain();this.fxGain.connect(this.master);this.skidGain=this.ctx.createGain();this.skidNoise=this.ctx.createBufferSource();this.skidNoise.buffer=this.noiseBuffer(1);this.skidNoise.loop=true;const sf=this.ctx.createBiquadFilter();sf.type="bandpass";sf.frequency.value=1450;sf.Q.value=.7;this.skidNoise.connect(sf).connect(this.skidGain).connect(this.fxGain);this.skidNoise.start();this.ambGain=this.ctx.createGain();this.ambNoise=this.ctx.createBufferSource();this.ambNoise.buffer=this.noiseBuffer(2);this.ambNoise.loop=true;const af=this.ctx.createBiquadFilter();af.type="lowpass";af.frequency.value=480;this.ambNoise.connect(af).connect(this.ambGain).connect(this.master);this.ambNoise.start();this.started=true;this.applyVolumes()},noiseBuffer(sec){const b=this.ctx.createBuffer(1,this.ctx.sampleRate*sec,this.ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;return b},resume(){if(this.ctx?.state==="suspended")this.ctx.resume()},applyVolumes(){if(!this.started)return;this.master.gain.setTargetAtTime(state.audio.master,this.ctx.currentTime,.03);this.engineGain.gain.setTargetAtTime(.16*state.audio.engine,this.ctx.currentTime,.03);this.exhaustGain.gain.setTargetAtTime(.035*state.audio.effects,this.ctx.currentTime,.03);this.fxGain.gain.setTargetAtTime(state.audio.effects,this.ctx.currentTime,.03);this.ambGain.gain.setTargetAtTime(.025*state.audio.ambience,this.ctx.currentTime,.1)},update(s,v){if(!this.started)return;this.resume();const t=this.ctx.currentTime,kind=v?.audio||"race",profiles={bike:[62,1.35,1.0],scooter:[50,1.15,.8],diesel:[34,.78,1.35],race:[58,1.25,.95],sport:[72,1.5,.85]};const [base,throttleTone,exhaustTone]=profiles[kind]||profiles.race;const rpmNorm=Math.min(1,s.rpm/7600),load=Math.min(1,Math.abs(s.speed)/Math.max(1,(v?.maxKmh||180)/3.6)),throttle=keys.up?1:0;this.engineOsc.frequency.setTargetAtTime(base+rpmNorm*base*throttleTone*3,t,.025);this.engineOsc2.frequency.setTargetAtTime(base*.5+rpmNorm*base*throttleTone*1.6,t,.03);this.engineFilter.frequency.setTargetAtTime(260+rpmNorm*5200,t,.05);this.engineGain.gain.setTargetAtTime((.025+rpmNorm*.18)*(0.55+throttle*.65)*state.audio.engine,t,.05);this.exhaustFilter.frequency.setTargetAtTime(280+rpmNorm*2600*exhaustTone,t,.06);this.exhaustGain.gain.setTargetAtTime((state.exhaustStyle==="stock"?.008:.018)+rpmNorm*.025*state.audio.effects,t,.08);this.turboOsc.frequency.setTargetAtTime(720+rpmNorm*1250,t,.05);this.turboGain.gain.setTargetAtTime((s.nitroActive?.035:0)+Math.max(0,rpmNorm-.58)*.012,t,.04);const skid=Math.min(1,s.drift*1.45)*(load>.18?1:0);this.skidGain.gain.setTargetAtTime(skid*.09*state.audio.effects,t,.04);this.ambGain.gain.setTargetAtTime(.018*state.audio.ambience*(state.night?.85:1),t,.2)},oneShot(freq,dur,gain,type="sine"){if(!this.started)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0.0001,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(Math.max(.0001,gain)*state.audio.effects,this.ctx.currentTime+.008);g.gain.exponentialRampToValueAtTime(.0001,this.ctx.currentTime+dur);o.connect(g).connect(this.fxGain);o.start();o.stop(this.ctx.currentTime+dur+.02)},brake(){this.oneShot(175,.09,.035,"triangle")},collision(strength=1){if(!this.started||this.ctx.currentTime-this.lastCollision<.15)return;this.lastCollision=this.ctx.currentTime;this.oneShot(82,.22,.12*strength,"sawtooth");this.oneShot(42,.3,.07*strength,"square")},raceBeep(freq=740){this.oneShot(freq,.12,.055,"sine")}};
addEventListener("pointerdown",e=>{if(!state.photoMode)return;state.photoDragging=true;state.photoLastX=e.clientX;state.photoLastY=e.clientY});addEventListener("pointermove",e=>{if(!state.photoMode||!state.photoDragging)return;state.photoYaw-=(e.clientX-state.photoLastX)*.008;state.photoPitch=THREE.MathUtils.clamp(state.photoPitch+(e.clientY-state.photoLastY)*.006,-.55,.7);state.photoLastX=e.clientX;state.photoLastY=e.clientY});addEventListener("pointerup",()=>{state.photoDragging=false});addEventListener("wheel",e=>{if(!state.photoMode)return;e.preventDefault();state.photoDistance=THREE.MathUtils.clamp(state.photoDistance+e.deltaY*.012,3,18)},{passive:false});
