addEventListener("keydown",e=>{if(rebindingAction)return;const k=e.key.toLowerCase();if(k==="e"&&state.gameStarted){e.preventDefault();if(state.onFoot){interactOnFoot()}else{exitVehicle()}}if(k==="o"&&state.gameStarted){document.getElementById("phase30Panel")?.classList.toggle("open");renderPhase30Tab("events")}});

/* ==================== PHASE 31–50 SYSTEM PACK ==================== */
const P31_KEY="zyrexDrivePhase31to50_v1";
const p31Defaults={fuel:78,fuelMax:78,driveMode:"normal",tcs:true,abs:true,traction:1,tireSize:1,suspensionType:"street",outfit:"street",reputation:0,challengeBest:null,saveSlot:1,tutorialSeen:false,storm:false,cityDistrict:"CENTRAL",trafficDensity:1};
const p31={...p31Defaults};
const phase50={fuelTick:0,fuelWarn:false,toastTimer:0,activeChallenge:null,challengeTime:0,challengeDistance:0,challengeSpeedPeak:0,selectedSave:1,expanded:false};
const phaseMissions=[
 {id:"taxi-pasar",name:"CITY TAXI · PASAR",desc:"Antar penumpang ke Pasar sebelum waktu habis.",target:20,time:70,reward:3500,xp:150},
 {id:"night-run",name:"NIGHT RUN · KAMPUNG",desc:"Tempuh rute malam sampai Kampung.",target:-100,time:95,reward:4200,xp:180},
 {id:"fuel-run",name:"FUEL RUN · SPBU",desc:"Datang ke SPBU dengan sisa bensin aman.",target:28,time:80,reward:2800,xp:120}
];
function p31Save(){try{localStorage.setItem(P31_KEY,JSON.stringify({...p31,savedAt:new Date().toISOString()}))}catch{}}
function loadPhase31to50(){try{const d=JSON.parse(localStorage.getItem(P31_KEY)||"null");if(d)Object.assign(p31,p31Defaults,d);state.fuel=p31.fuel;state.fuelMax=p31.fuelMax;state.phase31={...state.phase31,...p31}}catch{} }
function p31Toast(t){const el=document.getElementById('phase50Toast');if(!el)return;el.textContent=t;el.classList.add('show');phase50.toastTimer=2.5}
function phase50Money(n){return "Rp "+Math.round(n).toLocaleString("id-ID")}
function nearestGas(){let best=null,bd=Infinity;for(const q of worldFx.pois||[]){if(q.type!=="gas")continue;const d=Math.hypot(q.position.x-(vehicleRoot?.position.x||0),q.position.z-(vehicleRoot?.position.z||0));if(d<bd){bd=d;best=q}}return best&&bd<9?{poi:best,d:bd}:null}
function refuel(){const g=nearestGas();if(!g){p31Toast('Dekati SPBU ZYREX untuk isi bensin');return}const need=Math.max(0,p31.fuelMax-p31.fuel);if(need<1){p31Toast('Tangki masih penuh');return}const price=Math.ceil(need*70);if(!spend(price,'Isi bensin'))return;p31.fuel=p31.fuelMax;state.fuel=p31.fuel;p31Save();p31Toast(`FULL TANK · ${phase50Money(price)}`)}
function cycleDriveMode(){const a=['eco','normal','sport'];const i=a.indexOf(p31.driveMode);p31.driveMode=a[(i+1)%a.length];state.phase31.driveMode=p31.driveMode;p31Save();p31Toast(`DRIVE MODE · ${p31.driveMode.toUpperCase()}`)}
function startPhaseChallenge(type){if(!state.gameStarted||state.onFoot){p31Toast('Mulai driving dulu');return}if(phase50.activeChallenge){p31Toast('Challenge sedang berjalan');return}const target=type==='speed'?100:300;phase50.activeChallenge=type;phase50.challengeTime=type==='speed'?45:65;phase50.challengeDistance=0;phase50.challengeSpeedPeak=0;p31Toast(type==='speed'?'SPEED TRIAL · GO!':'DISTANCE TRIAL · GO!')}
function updateChallenge(dt){if(!phase50.activeChallenge||!state.gameStarted||state.onFoot)return;phase50.challengeTime-=dt;phase50.challengeDistance+=Math.abs(state.speed)*dt;phase50.challengeSpeedPeak=Math.max(phase50.challengeSpeedPeak,Math.abs(state.speed)*3.6);let success=false;if(phase50.activeChallenge==='speed'&&phase50.challengeSpeedPeak>=100)success=true;if(phase50.activeChallenge==='distance'&&phase50.challengeDistance>=300)success=true;if(success){const reward=phase50.activeChallenge==='speed'?4000:3200;const xp=phase50.activeChallenge==='speed'?180:130;earn(reward,'Phase 31–50 challenge');addXP(xp,'Challenge XP');p31.reputation+=5;p31.challengeBest=phase50.challengeTime;p31Save();p31Toast(`CHALLENGE COMPLETE · +${phase50Money(reward)}`);phase50.activeChallenge=null} else if(phase50.challengeTime<=0){p31Toast('Challenge gagal · coba lagi');phase50.activeChallenge=null}}
function updateFuel(dt){if(!state.gameStarted||state.onFoot||!isOwned(current?.id))return;const moving=Math.abs(state.speed)>2;const throttle=keys.up?1:0;const spec=vehicleSpec(current);let rate=moving?(0.018+Math.abs(state.speed)*.0025)*(current.type==='bike'?.65:1):0;if(throttle)rate*=1.45;if(p31.driveMode==='eco')rate*=.72;if(p31.driveMode==='sport')rate*=1.22;p31.fuel=Math.max(0,p31.fuel-rate*dt);state.fuel=p31.fuel;if(p31.fuel<=0){state.speed*=Math.max(0,1-2.8*dt);if(!phase50.fuelWarn){phase50.fuelWarn=true;p31Toast('BENSIN HABIS · Cari SPBU');}}else if(p31.fuel>4)phase50.fuelWarn=false;phase50.fuelTick+=dt;if(phase50.fuelTick>2){phase50.fuelTick=0;p31Save()}}
function addDistricts(){if(world.getObjectByName('ZYREX_DISTRICTS'))return;const g=new THREE.Group();g.name='ZYREX_DISTRICTS';const defs=[['KAMPUNG BARU',-38,-150,0x6c5140],['CITY MARKET',38,150,0x5d6045],['REST AREA',-48,95,0x4f5c67]];defs.forEach(([n,x,z,c])=>{const b=new THREE.Mesh(new THREE.BoxGeometry(12,4,10),mat(c,.88,.08));b.position.set(x,2,z);b.castShadow=true;g.add(b);const lab=makeLabel(n);lab.scale.set(.7,.7,.7);lab.position.set(x,4.5,z);g.add(lab)});world.add(g)}
function updateTrafficDensity(){const d=p31.trafficDensity||1;worldFx.traffic.forEach((v,i)=>v.visible=(i/Math.max(1,worldFx.traffic.length))<d)}
function phase50Mission(id){const m=phaseMissions.find(x=>x.id===id);if(!m){return}if(!state.gameStarted||state.onFoot){p31Toast('Mulai driving dulu');return}if(phase50.activeMission){p31Toast('Selesaikan misi aktif dulu');return}phase50.activeMission={...m,started:performance.now()};p31Toast(`MISSION START · ${m.name}`)}
function updatePhaseMissions(dt){const m=phase50.activeMission;if(!m||!state.gameStarted||state.onFoot)return;const elapsed=(performance.now()-m.started)/1000;if(Math.abs(state.z-m.target)<9){earn(m.reward,`Mission · ${m.name}`);addXP(m.xp,`Mission XP · ${m.name}`);p31.reputation+=8;p31Save();p31Toast(`MISSION COMPLETE · +${phase50Money(m.reward)}`);phase50.activeMission=null}else if(elapsed>m.time){p31Toast(`MISSION FAILED · ${m.name}`);phase50.activeMission=null}}
function saveSlot(slot){const payload={economy,progression,character:state.character,p31:{...p31},mods:collectMods(),activeVehicle:vehicleSelect.value,savedAt:new Date().toISOString()};try{localStorage.setItem(`zyrexSaveSlot_${slot}`,JSON.stringify(payload));p31Toast(`SAVE SLOT ${slot} · SAVED`)}catch{p31Toast('Save slot gagal')}}
function loadSlot(slot){try{const d=JSON.parse(localStorage.getItem(`zyrexSaveSlot_${slot}`)||'null');if(!d){p31Toast(`SAVE SLOT ${slot} kosong`);return}if(d.economy)Object.assign(economy,d.economy);if(d.progression)Object.assign(progression,d.progression);if(d.character)Object.assign(state.character,d.character);if(d.p31)Object.assign(p31,p31Defaults,d.p31);state.fuel=p31.fuel;state.fuelMax=p31.fuelMax;if(d.mods)Object.entries(d.mods).forEach(([id,v])=>localStorage.setItem('zyrexMod_'+id,JSON.stringify(v)));saveEconomy();applyCharacterVisuals();updateEconomyUI();updateMenuProfile();if(d.activeVehicle&&catalog.some(v=>v.id===d.activeVehicle))loadVehicle(d.activeVehicle);p31Toast(`SAVE SLOT ${slot} · LOADED`)}catch{p31Toast('Save slot rusak')}}
function exportProfile(){const payload={version:50,profile:collectProfile(),phase31to50:p31};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='zyrex-drive-profile-v50.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);p31Toast('PROFILE EXPORT READY')}
function setupPhase31to50UI(){
 if(document.getElementById('phase50Panel'))return;
 addDistricts();
 const box=document.createElement('aside');box.id='phase50Panel';box.className='phase50-panel';box.innerHTML=`<div class="p50-head"><div><span class="eyebrow">PHASE 31–50</span><h2>ZYREX WORLD SYSTEMS</h2></div><button id="p50Close">×</button></div><div class="p50-tabs"><button data-p50tab="vehicle">VEHICLE</button><button data-p50tab="city">CITY</button><button data-p50tab="missions">MISSIONS</button><button data-p50tab="profile">PROFILE</button></div><div id="p50Content"></div>`;document.querySelector('.viewport')?.appendChild(box);
 const hud=document.createElement('div');hud.id='phase50Hud';hud.innerHTML='<div><small>FUEL</small><strong id="p50Fuel">78%</strong></div><div><small>MODE</small><strong id="p50Mode">NORMAL</strong></div><div><small>REP</small><strong id="p50Rep">0</strong></div><div><small>CHALLENGE</small><strong id="p50Challenge">—</strong></div>';document.querySelector('.viewport')?.appendChild(hud);
 const toast=document.createElement('div');toast.id='phase50Toast';document.querySelector('.viewport')?.appendChild(toast);
 document.getElementById('p50Close').onclick=()=>box.classList.remove('open');document.querySelectorAll('[data-p50tab]').forEach(b=>b.onclick=()=>renderP50(b.dataset.p50tab));renderP50('vehicle');updateP50HUD();document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='l'&&state.gameStarted){refuel()}if(k==='b'&&state.gameStarted){cycleDriveMode()}if(k==='h'&&state.gameStarted){box.classList.toggle('open');renderP50('vehicle')}});}
function renderP50(tab){const c=document.getElementById('p50Content');if(!c)return;const common=`<div class="p50-grid"><button id="p50Refuel">⛽ REFUEL</button><button id="p50ModeBtn">DRIVE MODE</button><button id="p50Speed">SPEED TRIAL</button><button id="p50Distance">DISTANCE TRIAL</button></div>`;if(tab==='vehicle'){c.innerHTML=`${common}<label>Traction <input id="p50Traction" type="range" min="0.85" max="1.15" step="0.01" value="${p31.traction}"></label><label>Tire size <input id="p50Tire" type="range" min="0.92" max="1.12" step="0.01" value="${p31.tireSize}"></label><label>Suspension <select id="p50Susp"><option value="street">Street</option><option value="sport">Sport</option><option value="comfort">Comfort</option></select></label><label><input id="p50Tcs" type="checkbox" ${p31.tcs?'checked':''}> Traction control</label><label><input id="p50Abs" type="checkbox" ${p31.abs?'checked':''}> ABS assist</label>`;document.getElementById('p50Susp').value=p31.suspensionType;document.getElementById('p50Refuel').onclick=refuel;document.getElementById('p50ModeBtn').onclick=cycleDriveMode;document.getElementById('p50Speed').onclick=()=>startPhaseChallenge('speed');document.getElementById('p50Distance').onclick=()=>startPhaseChallenge('distance');document.getElementById('p50Traction').oninput=e=>{p31.traction=+e.target.value;state.phase31.traction=p31.traction;p31Save()};document.getElementById('p50Tire').oninput=e=>{p31.tireSize=+e.target.value;state.phase31.tireSize=p31.tireSize;p31Save()};document.getElementById('p50Susp').onchange=e=>{p31.suspensionType=e.target.value;state.phase31.suspensionType=p31.suspensionType;p31Save()};document.getElementById('p50Tcs').onchange=e=>{p31.tcs=e.target.checked;state.phase31.tcs=p31.tcs;p31Save()};document.getElementById('p50Abs').onchange=e=>{p31.abs=e.target.checked;state.phase31.abs=p31.abs;p31Save()};return}
 if(tab==='city'){c.innerHTML=`<div class="p50-card"><b>CITY DISTRICTS</b><p>Central Boulevard · Kampung Baru · City Market · Rest Area</p></div><label>Traffic density <input id="p50Traffic" type="range" min="0.35" max="1" step="0.05" value="${p31.trafficDensity}"></label><div class="p50-grid"><button id="p50Storm">STORM ${p31.storm?'ON':'OFF'}</button><button id="p50Gps">GPS</button><button id="p50Night">DAY / NIGHT</button></div>`;document.getElementById('p50Traffic').oninput=e=>{p31.trafficDensity=+e.target.value;updateTrafficDensity();p31Save()};document.getElementById('p50Storm').onclick=()=>{p31.storm=!p31.storm;setWeather(p31.storm?'rain':'clear');document.getElementById('p50Storm').textContent=`STORM ${p31.storm?'ON':'OFF'}`;p31Save()};document.getElementById('p50Gps').onclick=toggleNavigation;document.getElementById('p50Night').onclick=cycleTime;return}
 if(tab==='missions'){c.innerHTML=phaseMissions.map(m=>`<div class="p50-mission"><b>${m.name}</b><span>${m.desc}</span><small>${phase50Money(m.reward)} · ${m.xp} XP · ${m.time}s</small><button data-mission="${m.id}">START</button></div>`).join('')+`<div class="p50-mission"><b>LOCAL CHALLENGES</b><span>Speed Trial dan Distance Trial</span><small>Best: ${p31.challengeBest?Math.round(p31.challengeBest)+'s':'—'}</small></div>`;c.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>phase50Mission(b.dataset.mission));return}
 c.innerHTML=`<div class="p50-card"><b>REPUTATION</b><strong>${p31.reputation}</strong><p>Progress tersimpan di browser.</p></div><div class="p50-grid"><button data-slot="1">SAVE 1</button><button data-slot="2">SAVE 2</button><button data-slot="3">SAVE 3</button><button id="p50Export">EXPORT JSON</button></div><label>Character outfit<select id="p50Outfit"><option value="street">Street</option><option value="racing">Racing</option><option value="night">Night</option></select></label><button id="p50Tutorial">SHOW TUTORIAL</button>`;c.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>saveSlot(+b.dataset.slot));document.getElementById('p50Export').onclick=exportProfile;document.getElementById('p50Outfit').value=p31.outfit;document.getElementById('p50Outfit').onchange=e=>{p31.outfit=e.target.value;p31Save();p31Toast('OUTFIT SAVED')};document.getElementById('p50Tutorial').onclick=()=>showP50Tutorial()}
function showP50Tutorial(){const el=document.getElementById('phase50Toast');if(el){el.textContent='TIP: E keluar/masuk kendaraan · L refuel · B drive mode · H systems · G GPS · P race';el.classList.add('show');phase50.toastTimer=5}}
function updateP50HUD(){const f=document.getElementById('p50Fuel'),m=document.getElementById('p50Mode'),r=document.getElementById('p50Rep'),ch=document.getElementById('p50Challenge');if(f)f.textContent=`${Math.round((p31.fuel/p31.fuelMax)*100)}%`;if(m)m.textContent=p31.driveMode.toUpperCase();if(r)r.textContent=String(p31.reputation);if(ch)ch.textContent=phase50.activeChallenge?`${phase50.activeChallenge.toUpperCase()} ${Math.max(0,Math.ceil(phase50.challengeTime))}s`:'—'}
function updatePhase31to50(dt){if(!document.getElementById('phase50Panel'))return;state.phase31={...state.phase31,...p31};updateFuel(dt);updateChallenge(dt);updatePhaseMissions(dt);updateP50HUD();phase50.toastTimer=Math.max(0,phase50.toastTimer-dt);document.getElementById('phase50Toast')?.classList.toggle('show',phase50.toastTimer>0);if(state.playSeconds%10<dt)p31Save()}


// --- PHASE 71–100: Online multiplayer lobby, presence, room sync, chat and reconnect ---
const mp={room:null,rooms:[],players:new Map(),timer:0,heartbeat:0,ready:false,lastError:'',connected:false,remoteRoots:new Map(),chat:[],name:'',ws:null,wsAuthed:false,wsRetry:0,race:null};
function mpToken(){return localStorage.getItem('zyrexOnlineToken')||''}
async function mpReq(url,options={}){if(!mpToken())throw Error('Login online dulu');return onlineRequest(url,options)}
function mpToast(t){onlineToast('MP · '+t)}
function mpWsSend(type,data={}){if(mp.ws?.readyState===WebSocket.OPEN)mp.ws.send(JSON.stringify({type,...data}));}
function mpWsClose(){try{mp.ws?.close()}catch{}mp.ws=null;mp.wsAuthed=false}
function mpHandleWs(m){
  if(m.type==='auth:ok'){mp.wsAuthed=true;mpWsSend('room:join',{roomId:mp.room});return}
  if(m.type==='room:state'){mp.connected=true;mp.players=new Map(m.players.map(p=>[p.username,p]));mp.chat=m.chat||[];mp.race=m.race||null;mpRenderPlayers(m.players);mpRefreshUI();return}
  if(m.type==='player:transform'){const p=m.player;mp.players.set(p.username,p);mpRenderPlayers([...mp.players.values()]);return}
  if(m.type==='player:joined'||m.type==='player:ready'){if(mp.room)mpRefresh();return}
  if(m.type==='chat'){mp.chat.push(m.message);mp.chat=mp.chat.slice(-30);mpRefreshUI();return}
  if(m.type==='race:starting'){mp.race=m.race;mpToast('MULTIPLAYER RACE STARTING');return}
  if(m.type==='race:started'){mp.race=m.race;mpToast('GO! SERVER RACE STARTED');return}
  if(m.type==='server:snapshot'){const me=m.room?.players?.find?.(p=>p.username===mp.name);if(me){phase150.serverCorrection=Math.hypot((vehicleRoot?.position.x||0)-me.x,(vehicleRoot?.position.z||0)-me.z)}return}
  if(m.type==='race:finish'){mpToast(`${m.result.username} FINISH ${Math.round(m.result.elapsed/1000)}s`);return}
  if(m.type==='objective:update'){phase300.objective=m.objective;phase300Render();return} if(m.type==='anti_cheat:warning'){mpToast('SERVER WARNING · '+m.kind);return} if(m.type==='ranked:result'){if(m.ratings?.[mp.name]!=null)phase300.rating=m.ratings[mp.name];phase300Render();return} if(m.type==='race:error'||m.type==='error'){mpToast(m.error||'Online error');return}
}
function mpConnect(){
  if(!mp.room||!mpToken()||mp.ws?.readyState===WebSocket.OPEN||mp.ws?.readyState===WebSocket.CONNECTING)return;
  mpWsClose(); const proto=location.protocol==='https:'?'wss':'ws'; const url=`${proto}://${location.host}/ws`; const ws=new WebSocket(url);mp.ws=ws;
  ws.onopen=()=>{mp.wsRetry=0;ws.send(JSON.stringify({type:'auth',token:mpToken()}));};
  ws.onmessage=e=>{try{mpHandleWs(JSON.parse(e.data))}catch{}};
  ws.onerror=()=>{};
  ws.onclose=()=>{mp.wsAuthed=false;mp.connected=false;mpRefreshUI();if(mp.room){const delay=Math.min(8000,1000*Math.max(1,++mp.wsRetry));setTimeout(()=>mpConnect(),delay)}};
}
function mpSendTransform(){if(!mp.room)return;const data={x:vehicleRoot?.position.x||0,z:vehicleRoot?.position.z||state.z,heading:state.heading,speed:state.speed,vehicle:current?.id||'e30_stance',color:state.character?.top||'#8b5cf6'};if(mp.wsAuthed)mpWsSend('player:transform',data);else mpHeartbeat()}
function mpStartRace(){if(!mp.room){mpToast('Join room dulu');return}mpWsSend('race:start')}

function mpColor(c){return /^#[0-9a-f]{6}$/i.test(c||'')?c:'#8b5cf6'}
function mpMakeCar(color){const g=new THREE.Group();const body=new THREE.Mesh(new THREE.BoxGeometry(1.7,.55,3.5),mat(new THREE.Color(mpColor(color)),.55,.25));body.position.y=.55;g.add(body);const roof=new THREE.Mesh(new THREE.BoxGeometry(1.35,.42,1.5),mat(0x22242a,.5,.25));roof.position.set(0,.93,-.15);g.add(roof);for(const x of [-.75,.75])for(const z of [-1.15,1.15]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.28,.28,.18,12),mat(0x111217,.7,.1));w.rotation.z=Math.PI/2;w.position.set(x,.3,z);g.add(w)}return g}
function mpRemoveRemote(name){const r=mp.remoteRoots.get(name);if(r){scene.remove(r);mp.remoteRoots.delete(name)}}
function mpRenderPlayers(players){const seen=new Set();for(const p of players){seen.add(p.username);if(p.username===mp.name)continue;let r=mp.remoteRoots.get(p.username);if(!r){r=mpMakeCar(p.color);r.userData.target={x:p.x,z:p.z,heading:p.heading};scene.add(r);mp.remoteRoots.set(p.username,r)}r.userData.target={x:p.x,z:p.z,heading:p.heading};r.position.y=originalY;r.userData.label=p.username}for(const name of mp.remoteRoots.keys())if(!seen.has(name))mpRemoveRemote(name)}
function mpAnimateRemote(dt){for(const r of mp.remoteRoots.values()){const t=r.userData.target;if(!t)continue;r.position.x=THREE.MathUtils.lerp(r.position.x,t.x,Math.min(1,dt*8));r.position.z=THREE.MathUtils.lerp(r.position.z,t.z,Math.min(1,dt*8));r.rotation.y=THREE.MathUtils.lerp(r.rotation.y,t.heading,Math.min(1,dt*8))}}
async function mpCreate(){const name=String(document.getElementById('mpRoomName')?.value||`${onlineUser()||'Player'} Room`).trim();const id=String(document.getElementById('mpRoomId')?.value||'').trim();const d=await mpReq('/api/online/rooms',{method:'POST',body:JSON.stringify({name,roomId:id||undefined})});await mpJoin(d.id);mpToast('ROOM CREATED')}
async function mpList(){const d=await mpReq('/api/online/rooms');mp.rooms=d;const el=document.getElementById('mpRoomList');if(!el)return;el.innerHTML=d.length?d.map(r=>`<button class="mp-room" data-room="${r.id}"><b>${r.name}</b><span>${r.count}/${r.maxPlayers} · ${r.id}</span></button>`).join(''):'<div class="mp-empty">Belum ada room.</div>';el.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>mpJoin(b.dataset.room))}
async function mpJoin(id){const d=await mpReq('/api/online/join',{method:'POST',body:JSON.stringify({roomId:id})});mp.room=d.room.id;mp.name=d.player.username;mp.ready=false;mp.connected=true;localStorage.setItem('zyrexLastRoom',mp.room);mpToast(`JOINED ${mp.room}`);mpConnect();mpRefresh();mpList()}
async function mpLeave(){if(!mp.room)return;mpWsSend('room:leave');try{await mpReq('/api/online/leave',{method:'POST',body:JSON.stringify({roomId:mp.room})})}catch{}mpWsClose();for(const n of mp.remoteRoots.keys())mpRemoveRemote(n);mp.room=null;mp.connected=false;mp.ready=false;mp.race=null;mpToast('LEFT ROOM');mpRefreshUI()}
async function mpRefresh(){if(!mp.room)return;try{const d=await mpReq('/api/online/state?roomId='+encodeURIComponent(mp.room));mp.connected=true;mp.players=new Map(d.players.map(p=>[p.username,p]));mp.chat=d.chat||[];mpRenderPlayers(d.players);mpRefreshUI()}catch(e){mp.connected=false;mp.lastError=e.message;mpRefreshUI()}}
async function mpHeartbeat(){if(!mp.room)return;try{await mpReq('/api/online/heartbeat',{method:'POST',body:JSON.stringify({roomId:mp.room,x:vehicleRoot?.position.x||0,z:vehicleRoot?.position.z||state.z,heading:state.heading,speed:state.speed,vehicle:current?.id||'e30_stance',color:state.character?.top||'#8b5cf6',ready:mp.ready})});mp.connected=true}catch(e){mp.connected=false;mp.lastError=e.message}}
async function mpSetReady(){if(!mp.room)return;mp.ready=!mp.ready;try{if(mp.wsAuthed)mpWsSend('player:ready',{ready:mp.ready});else await mpReq('/api/online/ready',{method:'POST',body:JSON.stringify({roomId:mp.room,ready:mp.ready})});mpRefreshUI()}catch(e){mp.ready=!mp.ready;mpToast(e.message)}}
async function mpSendChat(){if(!mp.room)return;const input=document.getElementById('mpChatInput');const text=input?.value.trim();if(!text)return;try{if(mp.wsAuthed)mpWsSend('chat',{text});else await mpReq('/api/online/chat',{method:'POST',body:JSON.stringify({roomId:mp.room,text})});input.value='';if(!mp.wsAuthed)await mpRefresh()}catch(e){mpToast(e.message)}}
function mpRefreshUI(){const panel=document.getElementById('mpPanel');if(!panel)return;const st=document.getElementById('mpConn');if(st)st.textContent=mp.room?(mp.connected?`ROOM ${mp.room} · ${mp.players.size} PLAYERS`:'RECONNECTING…'):'OFFLINE';const ready=document.getElementById('mpReady');if(ready)ready.textContent=mp.ready?'UNREADY':'READY';const list=document.getElementById('mpPlayers');if(list)list.innerHTML=mp.room?[...mp.players.values()].map(p=>`<div class="mp-player"><b>${p.username}${p.username===mp.name?' · YOU':''}</b><span>${p.ready?'READY':'NOT READY'}</span></div>`).join(''):'<div class="mp-empty">Join room untuk melihat pemain.</div>';const chat=document.getElementById('mpChat');if(chat){chat.innerHTML=mp.chat.map(c=>`<div><b>${c.username}</b> ${c.text}</div>`).join('');chat.scrollTop=chat.scrollHeight}}
function setupPhase71to100UI(){if(document.getElementById('mpPanel'))return;const v=document.querySelector('.viewport');if(!v)return;const p=document.createElement('aside');p.id='mpPanel';p.innerHTML=`<div class="mp-head"><div><span class="eyebrow">PHASE 71–100</span><h2>ONLINE WORLD</h2></div><button id="mpClose">×</button></div><div id="mpConn" class="mp-conn">OFFLINE</div><div class="mp-card"><b>ROOM</b><div class="mp-inputs"><input id="mpRoomName" maxlength="32" placeholder="Room name"><input id="mpRoomId" maxlength="16" placeholder="Room ID (optional)"></div><button id="mpCreate">CREATE ROOM</button><button id="mpRefreshRooms">REFRESH ROOMS</button><div id="mpRoomList" class="mp-room-list"></div></div><div class="mp-card"><b>PLAYERS</b><div id="mpPlayers" class="mp-players"></div><button id="mpReady">READY</button><button id="mpRace">START ONLINE RACE</button><button id="mpLeave">LEAVE ROOM</button></div><div class="mp-card"><b>ROOM CHAT</b><div id="mpChat" class="mp-chat"></div><div class="mp-chat-row"><input id="mpChatInput" maxlength="120" placeholder="Message"><button id="mpChatSend">SEND</button></div></div><div class="mp-note">Online multiplayer: WebSocket realtime + HTTP fallback, room sync, ready state, remote vehicles, chat, reconnect. Race session divalidasi server; physics kendaraan belum authoritative.</div></aside>`;v.appendChild(p);const st=document.createElement('style');st.textContent=`#mpPanel{position:absolute;left:18px;top:18px;width:min(390px,calc(100% - 36px));max-height:calc(100% - 36px);overflow:auto;z-index:40;display:none;padding:16px;background:rgba(7,8,12,.95);border:1px solid rgba(255,255,255,.12);border-radius:18px;color:#eef1f7;box-shadow:0 25px 100px rgba(0,0,0,.55);font:600 11px/1.4 system-ui}#mpPanel.open{display:block}.mp-head{display:flex;justify-content:space-between}.mp-head h2{margin:3px 0 0}.mp-head button{background:transparent;border:0;color:#fff;font-size:24px}.mp-conn{margin:12px 0;padding:8px;border-radius:9px;background:#141720;font-weight:800}.mp-card{padding:11px;margin:8px 0;border:1px solid #2b2e38;background:#101219;border-radius:12px}.mp-card>b{display:block;margin-bottom:8px}.mp-inputs{display:grid;gap:6px}.mp-card input{box-sizing:border-box;width:100%;padding:9px;border:1px solid #343844;background:#171922;color:#fff;border-radius:8px}.mp-card button{width:100%;padding:8px;margin-top:6px;border:1px solid #343844;background:#171922;color:#fff;border-radius:8px;font-weight:800}.mp-room-list{display:grid;gap:5px;margin-top:8px}.mp-room{text-align:left!important;display:flex;justify-content:space-between;gap:8px}.mp-room span{opacity:.55}.mp-players{display:grid;gap:5px}.mp-player{display:flex;justify-content:space-between;padding:7px;background:#171922;border-radius:7px}.mp-player span{opacity:.55}.mp-chat{height:150px;overflow:auto;background:#090b10;padding:8px;border-radius:8px}.mp-chat div{margin:4px 0}.mp-chat b{color:#b8a8ff}.mp-chat-row{display:grid;grid-template-columns:1fr 80px;gap:5px}.mp-note,.mp-empty{opacity:.55;font-size:10px;margin-top:8px;line-height:1.5}@media(max-width:700px){#mpPanel{top:80px;width:calc(100% - 24px);left:12px}}`;document.head.appendChild(st);document.getElementById('mpClose').onclick=()=>p.classList.remove('open');document.getElementById('mpCreate').onclick=()=>mpCreate().catch(e=>mpToast(e.message));document.getElementById('mpRefreshRooms').onclick=()=>mpList().catch(e=>mpToast(e.message));document.getElementById('mpReady').onclick=()=>mpSetReady().catch(e=>mpToast(e.message));document.getElementById('mpRace').onclick=()=>mpStartRace();document.getElementById('mpLeave').onclick=()=>mpLeave();document.getElementById('mpChatSend').onclick=()=>mpSendChat();document.getElementById('mpChatInput').addEventListener('keydown',e=>{if(e.key==='Enter')mpSendChat()});const menu=document.querySelector('.menu-actions');if(menu){const b=document.createElement('button');b.id='menuMpBtn';b.type='button';b.textContent='MULTIPLAYER';b.onclick=()=>{p.classList.add('open');if(mpToken()){mpList().catch(()=>{});mpRefresh()}};menu.appendChild(b)}mpRefreshUI()}
